function validate([grid]) {
  if (grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 1000) return 'Each row needs 1 to 1000 cells.';
  if (grid.some(row => row.length !== cols)) return 'All rows of grid must have the same length.';
  if (grid.some(row => row.some(ch => ch !== 'X' && ch !== 'Y' && ch !== '.'))) return "Each cell is 'X', 'Y' or '.'.";
  return null;
}

