function numberOfSubmatrices(grid) {
  const cols = grid[0].length;
  const columnX = new Array(cols).fill(0);
  const columnY = new Array(cols).fill(0);
  let count = 0;
  for (const row of grid) {
    let xCount = 0;
    let yCount = 0;
    for (let j = 0; j < cols; j++) {
      if (row[j] === 'X') {
        columnX[j]++;
      } else if (row[j] === 'Y') {
        columnY[j]++;
      }
      xCount += columnX[j];
      yCount += columnY[j];
      if (xCount > 0 && xCount === yCount) {
        count++;
      }
    }
  }
  return count;
}

