function numberOfSubmatrices(grid) {
  // Count the X and Y cells of every top-left block from scratch.
  let answer = 0;
  for (let bottom = 0; bottom < grid.length; bottom++)
    for (let right = 0; right < grid[0].length; right++) {
      const cells = grid.slice(0, bottom + 1).flatMap(r => r.slice(0, right + 1));
      const xs = cells.filter(ch => ch === 'X').length;
      const ys = cells.filter(ch => ch === 'Y').length;
      if (xs >= 1 && xs === ys) answer++;
    }
  return answer;
}

