function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const rows = size === 'large' ? int(80, 100) : int(1, 5);
  const cols = size === 'large' ? int(80, 100) : int(1, 5);
  // 0: checkerboard, 1: each pair of columns balances within a row, 2: random cells.
  const mode = int(0, 2);
  const first = rand() < 0.5 ? 'X' : 'Y';
  const dot = rand() * 0.5;
  const pick = () => (rand() < dot ? '.' : rand() < 0.5 ? 'X' : 'Y');
  const grid = [];
  for (let i = 0; i < rows; i++) {
    const row = [];
    for (let j = 0; j < cols; j++) {
      if (mode === 0) row.push((i + j) % 2 === 0 ? first : first === 'X' ? 'Y' : 'X');
      else if (mode === 1 && j % 2 === 1) row.push(row[j - 1] === 'X' ? 'Y' : row[j - 1] === 'Y' ? 'X' : '.');
      else row.push(pick());
    }
    grid.push(row);
  }
  return [grid];
}
